function isNgForOf({ node, index }) {
  return (
    node.type === "NGMicrosyntaxKeyedExpression" &&
    node.key.name === "of" &&
    index === 1
  );
}

function isNgForOfTrack(path) {
  const { node } = path;
  return (
    path.parent.body[1].key.name === "of" &&
    node.type === "NGMicrosyntaxKeyedExpression" &&
    node.key.name === "track" &&
    node.key.type === "NGMicrosyntaxKey"
